_ex = ['A shop sends 200 supplier invoices a month to a processing service for 1.20 each, which is 240 against 6 hours of its own time. Amounts are in your currency.', 'Invoice process: receive, check, enter, match, approve, file. Exception: a missing PO number goes back to the client within one day.', 'Service-level agreement (SLA): 95% of invoices processed in 24 hours; accuracy 98%; weekly report on Mondays.', 'A new person reaches target accuracy after 2 days using the checklist and sample data.', '100 items checked: 3 errors = 97%. Below 98%, so a check is added for amounts.', '300 tasks at 6 minutes = 1,800 minutes = 30 hours; one person does 6 hours a day: 5 person-days.', 'A staff member needs only the invoice folder; access to bank files is not given.', 'Report: 640 done, 97.5% on time, 98.4% accurate. Suggestion: add a drop-down for tax codes.']
_extra = ['List what the client must supply and by when.', 'Agree who answers questions and how fast.', "Write the process owner's name on the map.", "Create a short glossary for the client's terms.", 'Keep a log of changes to the procedure.', 'Review errors by cause weekly.', 'Check the pilot with a small group first.', 'Plan for staff leave and backups.', 'Check data export and transfer rules.', 'Keep a copy of all signed terms.', 'Remove access when anyone leaves.', 'Keep sample data apart from real data.', 'Share good practice with your team.', 'Ask the client for feedback each month.', 'Work out cost per task each quarter.', 'Write a 90-day plan with a quality target.']
C['deep']['mods'] = [(m[0], _ex[i], m[2]) for i, m in enumerate(C['deep']['mods'])]
C['deep']['extra'] = [_extra[2*i:2*i+2] for i in range(8)]
_np = [['List the tasks a client could hand over, such as data entry or customer email replies, and pick those that are repeatable, rule-based and measurable.', 'Compare doing the work in-house with outsourcing it, using cost per task, time saved and risk, and show the client the numbers side by side.'], ['Map the process in numbered steps showing inputs, outputs and decision points, and test the map by asking a new person to follow it alone.', 'Record how long each step takes across twenty real examples, and use the average to quote volume and price with confidence.'], ['State measurable service levels in the contract, such as 95 percent of tasks done within 24 hours and under 2 percent errors, and say how they will be reported.', 'Include the scope, how change requests are handled, payment terms, the notice period and a clear way to settle disagreements before work starts.'], ['Write step-by-step procedures with screenshots, and have each new team member complete a supervised practice batch before they handle live work.', 'Keep a short training log recording who learned what and when, and re-test staff every quarter on the most error-prone steps.'], ['Check a random sample, for example 10 percent of daily output, and record errors by type so the main cause can be found and fixed.', 'Add a second-person review for high-risk tasks, and pause work to investigate if the error rate passes the agreed limit twice in one week.'], ['Calculate capacity as tasks per person per hour multiplied by productive hours, for example 12 tasks an hour over 6 hours gives 72 tasks a day.', 'Plan for peaks by agreeing in advance an extra-volume rate and a notice period, so you can add temporary staff without lowering quality.'], ['Limit access to client data to named people, require unique passwords and screen locks, and remove access on the day someone leaves the team.', 'Have every worker sign a confidentiality agreement, store files only on approved systems, and report any suspected data breach to the client immediately.'], ['Send the client a weekly report showing volume, on-time rate, error rate and open issues, in the same layout every time.', 'Hold a monthly review to agree one improvement, such as removing a step that causes 30 percent of errors, and measure the result the following month.']]
C['mods'] = [(m[0], m[1], list(m[2])+_np[i], m[3], m[4], m[5]) for i, m in enumerate(C['mods'])]

_dupfix = {"1": "A clinic sends 150 patient reminder calls a week to a call service at 0.80 each: 120 a week against 5 hours of nurse time. Amounts are in your currency.", "2": "Order entry: receive, check address, key in, confirm, ship note. Exception: an order with no phone number goes back to the shop the same day.", "3": "SLA: 90% of calls made within 4 hours; 99% of numbers dialled correctly; a daily summary sent at 5pm.", "4": "A new agent reaches 95% script accuracy after 3 days of shadowing and one set of test calls.", "5": "50 forms checked, 2 wrong: 96%. Below the 98% target, so a second reader is added for dates.", "6": "A team handles 1,200 chats a week at 5 minutes each: 6,000 minutes, or 100 hours; at 25 hours a person each week, 4 people are needed.", "7": "A temporary worker sees customer names but not card details; the card field is masked and access ends with the contract.", "8": "Report: 410 calls, 92% reached, 97% accurate; fix: move the call window to 6pm, when more people answer."}
C['deep']['mods'] = [(m[0], _dupfix.get(str(i + 1), m[1]), m[2]) for i, m in enumerate(C['deep']['mods'])]
C['intro_add'] = ['You will be able to choose which client tasks suit outsourcing and compare in-house cost with outsourced cost using real numbers.', 'You will be able to document a process in numbered steps and time each step to quote volume and price confidently.', 'You will be able to write a contract with measurable service levels, so both sides know what good work looks like.', 'You will be able to produce training procedures and logs that bring a new team member to a reliable standard quickly.', 'You will be able to sample outputs, categorise errors and set stop-and-investigate limits before the client notices a problem.', 'You will be able to calculate daily capacity from hourly rates and plan staffing, including agreed pricing for peak volumes.', 'You will be able to protect client data through named access, confidentiality agreements and prompt reporting of suspected breaches.', 'You will be able to send consistent weekly reports and agree one monthly improvement that clients can see in the numbers.']
